head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > undoAll]<br/>필터링된 상태를 기준으로 전체 Row 의 데이터와 상태값을 원본(Origin) 값으로 복원합니다.",
    "validation" : [
        "필터와 정렬이 적용된 상태를 기준으로 동작하며, 필터가 적용되지 않은 경우 전체 Row 데이터를 기준으로 동작합니다.",
        "Remove 계열의 메소드로 '제거' 된 'E' 상태의 Row 는 이전 상태값으로 복원할 수 없습니다.",
        "Insert 계열의 메소드로 '삽입' 된 'C' 상태의 Row 는 상태값과 데이터가 복원되지 않습니다.",
        "'삽입 후 삭제' 된 'V' 상태의 Row 는 'C' 상태값과 빈 데이터로 복원됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);

    insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert5","insert6","insert7","insert8"],true);

    target1.deleteRow(insertIndex);
};



scwin.btn_deleteRow_onclick = function (e) {
    target1.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_1", condition:'and'})
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"insert1", condition:'or'})        
        isFilter = true;
    }	

    scwin.btn_getAllJSON_onclick();
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }

    scwin.btn_getAllJSON_onclick();
};



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_undoAll_onclick = function (e) {
    target1.undoAll();

	scwin.btn_getAllJSON_onclick();
};
